def maxScoreWords(words, letters, score):
    from collections import Counter

    def dfs(index, current_score, remaining_letters):
        if index == len(words):
            return current_score

        # Option 1: Skip the current word
        max_score = dfs(index + 1, current_score, remaining_letters)

        # Option 2: Use the current word if possible
        word_counter = Counter(words[index])
        if all(remaining_letters[char] >= word_counter[char] for char in word_counter):
            word_score = sum(score[ord(char) - ord('a')] * word_counter[char] for char in word_counter)
            for char in word_counter:
                remaining_letters[char] -= word_counter[char]
            max_score = max(max_score, dfs(index + 1, current_score + word_score, remaining_letters))
            for char in word_counter:
                remaining_letters[char] += word_counter[char]

        return max_score

    letter_counts = Counter(letters)
    return dfs(0, 0, letter_counts)
